USE marketing;

-- Backup dulu. CREATE TABLE IF NOT EXISTS supaya backup pertama
-- (yang berisi data ASLI) tidak tertimpa kalau script dijalankan 2x.
CREATE TABLE IF NOT EXISTS _backup_teks_asli (
  tabel  VARCHAR(32)  NOT NULL,
  id     INT          NOT NULL,
  teks   TEXT,
  PRIMARY KEY (tabel, id)
) COMMENT 'Isi kolom teks sebelum diganti oleh 04_komentar_realistis.sql';

INSERT IGNORE INTO _backup_teks_asli (tabel, id, teks)
  SELECT 'customer_feedback', id, komentar FROM customer_feedback;
INSERT IGNORE INTO _backup_teks_asli (tabel, id, teks)
  SELECT 'lead_activity', id, catatan FROM lead_activity;
INSERT IGNORE INTO _backup_teks_asli (tabel, id, teks)
  SELECT 'survey_response', id, jawaban_teks FROM survey_response;

